Lemma rst0_region rid r : (s_regions st0) !! rid = Some r ->
  0 <= r_base r /\ r_base r + round_up_pg (r_len r) <= ATOP
  /\ (r_base r + round_up_pg (r_len r) <= 0x10000 \/ 0x12000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x12000 \/ 0x26000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x26000 \/ 0x27000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x27000 \/ 0x59000 <= r_base r).
Proof.
